public class BasicDeserializerFactory__addExplicitDelegatingCreator_TriageGen2Test {

    private BasicDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private CreatorCollector creators;

    // A subclass to expose the protected method for testing
    private static class TestableBasicDeserializerFactory extends BasicDeserializerFactory {
        protected TestableBasicDeserializerFactory() {
            super(null);
        }

        @Override
        protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
            return this;
        }

        @Override
        public void _addExplicitDelegatingCreator(DeserializationContext ctxt,
                                                 BeanDescription beanDesc,
                                                 CreatorCollector creators,
                                                 CreatorCandidate candidate) throws JsonMappingException {
            super._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicDeserializerFactory();
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        creators = mock(CreatorCollector.class);
    }

    /**
     * Test case: Single argument creator (argCount == 1).
     * This triggers the branch where it handles single argument creators and removes constructors.
     */
    @Test
    public void testSingleArgumentCreator() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        BeanPropertyDefinition propDef = mock(POJOPropertyBuilder.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(creator);
        when(candidate.parameter(0)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.propertyDef(0)).thenReturn(propDef);

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        // Verify _handleSingleArgumentCreator logic (via internal call simulation)
        // Since we can't easily mock the protected _handleSingleArgumentCreator directly without spy,
        // we verify the side effects on the property definition.
        verify(propDef).removeConstructors();
    }

    /**
     * Test case: Multiple arguments, one is delegating.
     * This should succeed and call addDelegatingCreator.
     */
    @Test
    public void testMultipleArgumentsWithOneDelegating() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);

        // 3 args: index 0 is delegating (not injected), index 1 is injected, index 2 is normal
        // Wait, the logic says: if injection != null, it's a property. 
        // If injection == null, it's the delegating one (ix).
        // Let's do: arg 0 (injectable), arg 1 (delegating), arg 2 (normal)

        when(candidate.paramCount()).thenReturn(3);
        when(candidate.creator()).thenReturn(creator);

        // Arg 0: Injected
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);
        JacksonInject.Value injectVal = mock(JacksonInject.Value.class);
        when(candidate.parameter(0)).thenReturn(param0);
        when(candidate.injection(0)).thenReturn(injectVal);

        // Arg 1: Delegating (ix becomes 1)
        AnnotatedParameter param1 = mock(AnnotatedParameter.class);
        when(candidate.parameter(1)).thenReturn(param1);
        when(candidate.injection(1)).thenReturn(null);

        // Arg 2: Normal (not injected, not ix) -> This would trigger "More than one argument" error.
        // To test success, we need exactly one non-injected argument.
        // Let's refine: 
        // Arg 0: Injected
        // Arg 1: Delegating
        // Arg 2: Injected
        AnnotatedParameter param2 = mock(AnnotatedParameter.class);
        when(candidate.parameter(2)).thenReturn(param2);
        when(candidate.injection(2)).thenReturn(injectVal);

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        // verify creators.addDelegatingCreator(creator, true, properties, 1)
        verify(creators).addDelegatingCreator(eq(creator), eq(true), any(SettableBeanProperty[].class), eq(1));
    }

    /**
     * Test case: Error - More than one argument left as delegating.
     */
    @Test(expected = JsonMappingException.class)
    public void testMoreThanOneDelegatingArgument() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(2);

        // Both are not injected, so both try to be the delegating argument
        when(candidate.parameter(0)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(0)).thenReturn(null);

        when(candidate.parameter(1)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(1)).thenReturn(null);

        // Mock ctxt to throw exception when reportBadTypeDefinition is called
        doThrow(new JsonMappingException(null, "error")).when(ctxt)
                .reportBadTypeDefinition(any(), anyString(), any(), any(), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
    }

    /**
     * Test case: Error - No argument left as delegating.
     */
    @Test(expected = JsonMappingException.class)
    public void testNoDelegatingArgument() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        when(candidate.paramCount()).thenReturn(2);

        // Both are injected, so ix remains -1
        JacksonInject.Value injectVal = mock(JacksonInject.Value.class);
        when(candidate.parameter(0)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(0)).thenReturn(injectVal);

        when(candidate.parameter(1)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(1)).thenReturn(injectVal);

        doThrow(new JsonMappingException(null, "error")).when(ctxt)
                .reportBadTypeDefinition(any(), anyString(), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
    }

    /**
     * Test case: Verify constructCreatorProperty is called for injected parameters.
     * Since constructCreatorProperty is protected in the same class, we spy the factory.
     */
    @Test
    public void testInjectedPropertyConstruction() throws JsonMappingException {
        TestableBasicDeserializerFactory spyFactory = spy(new TestableBasicDeserializerFactory());
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        JacksonInject.Value injectVal = mock(JacksonInject.Value.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        SettableBeanProperty mockProp = mock(SettableBeanProperty.class);

        when(candidate.paramCount()).thenReturn(2); // 1 injected, 1 delegating
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.injection(0)).thenReturn(injectVal);
        when(candidate.parameter(1)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(1)).thenReturn(null);

        doReturn(mockProp).when(spyFactory).constructCreatorProperty(any(), any(), any(), anyInt(), any(), any());

        spyFactory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        verify(spyFactory).constructCreatorProperty(eq(ctxt), eq(beanDesc), isNull(), eq(0), eq(param), eq(injectVal));
        verify(creators).addDelegatingCreator(any(), eq(true), any(SettableBeanProperty[].class), eq(1));
    }
}
